public enum ThreadArchiveStateActor: Codable, Sendable {
    case person(Person)
    case system(System)

    public init(from decoder: any Decoder) throws {
        let raw = try JSONValue(from: decoder)
        let tag = raw["type"]?.stringValue
        switch tag {
            case "person": self = .person(try raw.decode(Person.self))
            case "system": self = .system(try raw.decode(System.self))
            default:
                throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unknown type tag: \(tag ?? "nil")"))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
            case .person(let value): try value.encode(to: encoder)
            case .system(let value): try value.encode(to: encoder)
        }
    }
}

