    }
}

/// A processed variant of a media item, such as the original upload or a resized thumbnail, including a signed download URL resolved at request time.
public struct MediaVariant: Codable, Sendable {
    /// Size of the stored bytes.
    public var byteSize: Int??
    /// MIME type of this variant's file (e.g., `"image/jpeg"`, `"video/mp4"`). `null` if the file is not loaded.
    public var contentType: String??
    /// Stable authenticated API path for this image rendition's bytes (`/api/v1/media/:media/image?variant=...&file=...`). It changes only when the rendition's file is replaced and carries no signature. `null` for non-image variants or when the file is not loaded.
    public var contentUrl: String??
    /// When this variant was created (ISO 8601).
    public var createdAt: Date?
    /// Client-declared video duration in milliseconds; not server-probed.
    public var durationMs: Int??
    /// ID of the underlying storage file that backs this variant (`fil_...`).
    public var file: String?
    /// Original filename of the uploaded file for this variant. `null` if the file is not loaded.
    public var filename: String??
    /// Height of this variant in pixels. `null` if not recorded.
    public var height: Int??
    /// Media variant ID (`mvr_...`).
    public var id: String
    /// Resolved image delivery metadata for this variant, including dimensions and CDN URL. `null` for non-image content types.
    public var imageSource: ImageSource??
    /// Lowercase SHA-256 of the stored bytes.
    public var sha256: String??
    /// When this variant was last updated (ISO 8601).
    public var updatedAt: Date?
    /// Signed download URL for this variant, resolved at request time. `null` if the file is unavailable.
    public var url: String??
    /// Expiry of this variant's playable URL.
    public var urlExpiresAt: Date??
    /// Identifier for this variant's processing tier. Common values include `"original"` (the unmodified upload) and `"thumbnail"` (a resized preview).
    public var variantKey: String?
    /// Width of this variant in pixels. `null` if not recorded.
    public var width: Int??

    public init(
        byteSize: Int?? = nil,
        contentType: String?? = nil,
        contentUrl: String?? = nil,
        createdAt: Date? = nil,
        durationMs: Int?? = nil,
        file: String? = nil,
        filename: String?? = nil,
        height: Int?? = nil,
        id: String,
        imageSource: ImageSource?? = nil,
        sha256: String?? = nil,
        updatedAt: Date? = nil,
        url: String?? = nil,
        urlExpiresAt: Date?? = nil,
        variantKey: String? = nil,
        width: Int?? = nil
    ) {
        self.byteSize = byteSize
        self.contentType = contentType
        self.contentUrl = contentUrl
        self.createdAt = createdAt
        self.durationMs = durationMs
        self.file = file
        self.filename = filename
        self.height = height
        self.id = id
        self.imageSource = imageSource
        self.sha256 = sha256
        self.updatedAt = updatedAt
        self.url = url
        self.urlExpiresAt = urlExpiresAt
        self.variantKey = variantKey
        self.width = width
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.byteSize = try container.contains(.byteSize) ? .some(container.decodeIfPresent(Int.self, forKey: .byteSize)) : nil
        self.contentType = try container.contains(.contentType) ? .some(container.decodeIfPresent(String.self, forKey: .contentType)) : nil
        self.contentUrl = try container.contains(.contentUrl) ? .some(container.decodeIfPresent(String.self, forKey: .contentUrl)) : nil
        self.createdAt = try container.decodeIfPresent(Date.self, forKey: .createdAt)
        self.durationMs = try container.contains(.durationMs) ? .some(container.decodeIfPresent(Int.self, forKey: .durationMs)) : nil
        self.file = try container.decodeIfPresent(String.self, forKey: .file)
        self.filename = try container.contains(.filename) ? .some(container.decodeIfPresent(String.self, forKey: .filename)) : nil
        self.height = try container.contains(.height) ? .some(container.decodeIfPresent(Int.self, forKey: .height)) : nil
        self.id = try container.decode(String.self, forKey: .id)
        self.imageSource = try container.contains(.imageSource) ? .some(container.decodeIfPresent(ImageSource.self, forKey: .imageSource)) : nil
        self.sha256 = try container.contains(.sha256) ? .some(container.decodeIfPresent(String.self, forKey: .sha256)) : nil
        self.updatedAt = try container.decodeIfPresent(Date.self, forKey: .updatedAt)
        self.url = try container.contains(.url) ? .some(container.decodeIfPresent(String.self, forKey: .url)) : nil
        self.urlExpiresAt = try container.contains(.urlExpiresAt) ? .some(container.decodeIfPresent(Date.self, forKey: .urlExpiresAt)) : nil
        self.variantKey = try container.decodeIfPresent(String.self, forKey: .variantKey)
        self.width = try container.contains(.width) ? .some(container.decodeIfPresent(Int.self, forKey: .width)) : nil
    }

    private enum CodingKeys: String, CodingKey {
        case byteSize = "byte_size"
        case contentType = "content_type"
        case contentUrl = "content_url"
        case createdAt = "created_at"
        case durationMs = "duration_ms"
        case file
        case filename
        case height
        case id
        case imageSource = "image_source"
        case sha256
        case updatedAt = "updated_at"
        case url
        case urlExpiresAt = "url_expires_at"
        case variantKey = "variant_key"
        case width
    }
}

/// A rich attachment associated with a message, such as a file, scraped link, artifact, task, media item, or inline action.
public struct Attachment: Codable, Sendable {
    /// MIME type of the attached file, e.g. `"image/png"` or `"application/pdf"`. Present on `file`, `artifact`, and `media` types. `null` otherwise.
    public var contentType: String??
    /// Short description. The page meta-description for `scraped_link`, the artifact description for `artifact`, and the task description for `task` types. `null` on other types.
    public var description: String??
    /// Original filename of the attached file, e.g. `"report.pdf"`. Present on `file`, `artifact`, and `media` types. `null` otherwise.
    public var filename: String??
    /// Height in pixels of the media item. Present on `media` type only. `null` otherwise.
    public var height: Int??
    /// Unique identifier for this attachment within the message.
    public var id: String
    /// Height in pixels of the scraped preview image. Present on `scraped_link` type only. `null` otherwise.
    public var imageHeight: Int??
    /// Image source metadata for inline rendering. Present on `file`, `scraped_link`, `artifact`, and `media` types when the content is an image. `null` otherwise.
    public var imageSource: ImageSource??
    /// URL of the preview image extracted from the scraped page. Present on `scraped_link` type only. `null` otherwise.
    public var imageUrl: String??
    /// Width in pixels of the scraped preview image. Present on `scraped_link` type only. `null` otherwise.
    public var imageWidth: Int??
    /// For `structured_data` type, what the data is about as set by the sender (for example `"pr:14963"`), copied from the record so it can be read without `object`. Not unique. `null` when unset and on other types.
    public var key: String??
    /// The media category, e.g. `"video"` or `"audio"`. Present on `media` type only; omitted otherwise.
    public var mediaType: String?
    /// Display name of the media item. Present on `media` type only. `null` otherwise.
    public var name: String??
    /// The full embedded object payload. For `task` type, contains the task record. For `action` type, contains the action definition. For `chart` type, contains the chart with its inline `spec`. For `structured_data` type, contains the inline `data` and the `schema_url` or `schema_config` naming its JSON Schema. Omitted on other types.
    public var object: [String: JSONValue]?
    /// Display title. The page title for `scraped_link`, the artifact name for `artifact`, and the task title for `task` types. `null` on other types.
    public var title: String??
    /// The attachment type. One of `"file"`, `"scraped_link"`, `"artifact"`, `"task"`, `"media"`, `"action"`, `"chart"`, or `"structured_data"`. Determines which additional fields are present.
    public var type: String
    /// URL to access the resource. A signed download URL for `file` and `artifact` types; the original URL for `scraped_link`; a media playback URL for `media`. `null` on `task` and `action` types.
    public var url: String??
    /// Array of available encoding variants for the media item (e.g. different resolutions). Present on `media` type only; omitted otherwise.
    public var variants: [MediaVariant]?
    /// Version number of the attached artifact at the time of attachment. Present on `artifact` type only. `null` otherwise.
    public var version: Int??
    /// Width in pixels of the media item. Present on `media` type only. `null` otherwise.
    public var width: Int??

    public init(
        contentType: String?? = nil,
        description: String?? = nil,
        filename: String?? = nil,
        height: Int?? = nil,
        id: String,
        imageHeight: Int?? = nil,
        imageSource: ImageSource?? = nil,
        imageUrl: String?? = nil,
        imageWidth: Int?? = nil,
        key: String?? = nil,
        mediaType: String? = nil,
        name: String?? = nil,
        object: [String: JSONValue]? = nil,
        title: String?? = nil,
        type: String,
        url: String?? = nil,
        variants: [MediaVariant]? = nil,
        version: Int?? = nil,
        width: Int?? = nil
    ) {
        self.contentType = contentType
        self.description = description
        self.filename = filename
        self.height = height
        self.id = id
        self.imageHeight = imageHeight
        self.imageSource = imageSource
        self.imageUrl = imageUrl
        self.imageWidth = imageWidth
        self.key = key
        self.mediaType = mediaType
        self.name = name
        self.object = object
        self.title = title
        self.type = type
        self.url = url
        self.variants = variants
        self.version = version
        self.width = width
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.contentType = try container.contains(.contentType) ? .some(container.decodeIfPresent(String.self, forKey: .contentType)) : nil
        self.description = try container.contains(.description) ? .some(container.decodeIfPresent(String.self, forKey: .description)) : nil
        self.filename = try container.contains(.filename) ? .some(container.decodeIfPresent(String.self, forKey: .filename)) : nil
        self.height = try container.contains(.height) ? .some(container.decodeIfPresent(Int.self, forKey: .height)) : nil
        self.id = try container.decode(String.self, forKey: .id)
        self.imageHeight = try container.contains(.imageHeight) ? .some(container.decodeIfPresent(Int.self, forKey: .imageHeight)) : nil
        self.imageSource = try container.contains(.imageSource) ? .some(container.decodeIfPresent(ImageSource.self, forKey: .imageSource)) : nil
        self.imageUrl = try container.contains(.imageUrl) ? .some(container.decodeIfPresent(String.self, forKey: .imageUrl)) : nil
        self.imageWidth = try container.contains(.imageWidth) ? .some(container.decodeIfPresent(Int.self, forKey: .imageWidth)) : nil
        self.key = try container.contains(.key) ? .some(container.decodeIfPresent(String.self, forKey: .key)) : nil
        self.mediaType = try container.decodeIfPresent(String.self, forKey: .mediaType)
        self.name = try container.contains(.name) ? .some(container.decodeIfPresent(String.self, forKey: .name)) : nil
        self.object = try container.decodeIfPresent([String: JSONValue].self, forKey: .object)
        self.title = try container.contains(.title) ? .some(container.decodeIfPresent(String.self, forKey: .title)) : nil
        self.type = try container.decode(String.self, forKey: .type)
        self.url = try container.contains(.url) ? .some(container.decodeIfPresent(String.self, forKey: .url)) : nil
        self.variants = try container.decodeIfPresent([MediaVariant].self, forKey: .variants)
        self.version = try container.contains(.version) ? .some(container.decodeIfPresent(Int.self, forKey: .version)) : nil
