        let raw = try JSONValue(from: decoder)
        let tag = raw["type"]?.stringValue
        switch tag {
            case "d1_database": self = .d1Database(try raw.decode(D1Database.self))
            case "r2_bucket": self = .r2Bucket(try raw.decode(R2Bucket.self))
            default:
                throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unknown type tag: \(tag ?? "nil")"))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
            case .r2Bucket(let value): try value.encode(to: encoder)
            case .d1Database(let value): try value.encode(to: encoder)
        }
    }
}

