        let raw = try JSONValue(from: decoder)
        let tag = raw["type"]?.stringValue
        switch tag {
            case "active": self = .active(try raw.decode(Active.self))
            case "archived": self = .archived(try raw.decode(Archived.self))
            default:
                throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unknown type tag: \(tag ?? "nil")"))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
            case .active(let value): try value.encode(to: encoder)
            case .archived(let value): try value.encode(to: encoder)
        }
    }
}

