        instructions: String? = nil,
        isSystemSession: Bool? = nil,
        maxRunsPerTurn: Int? = nil,
        maxTokens: Int? = nil,
        maxTurns: Int? = nil,
        metadata: [String: JSONValue]? = nil,
        name: String? = nil,
        result: [String: JSONValue]? = nil,
        startedAt: Date? = nil,
        status: String? = nil,
        trajectory: String? = nil
    ) {
        self.agent = agent
        self.completedAt = completedAt
        self.createdAt = createdAt
        self.error = error
        self.id = id
        self.inbox = inbox
        self.instructions = instructions
        self.isSystemSession = isSystemSession
        self.maxRunsPerTurn = maxRunsPerTurn
        self.maxTokens = maxTokens
        self.maxTurns = maxTurns
        self.metadata = metadata
        self.name = name
        self.result = result
        self.startedAt = startedAt
        self.status = status
        self.trajectory = trajectory
    }

    private enum CodingKeys: String, CodingKey {
        case agent
        case completedAt = "completed_at"
        case createdAt = "created_at"
        case error
        case id
        case inbox
        case instructions
        case isSystemSession = "is_system_session"
        case maxRunsPerTurn = "max_runs_per_turn"
        case maxTokens = "max_tokens"
        case maxTurns = "max_turns"
        case metadata
        case name
        case result
        case startedAt = "started_at"
        case status
        case trajectory
    }
}

