    public var locallyEdited: Bool?
    /// Incoming value the field will be set to after the upgrade (string, number, boolean, or `null`).
    public var new: JSONValue?
    /// Current value of the field before the upgrade (string, number, boolean, or `null`).
    public var old: JSONValue?

    public init(
        baseline: JSONValue? = nil,
        field: String,
        locallyEdited: Bool? = nil,
        new: JSONValue? = nil,
        old: JSONValue? = nil
    ) {
        self.baseline = baseline
        self.field = field
        self.locallyEdited = locallyEdited
        self.new = new
        self.old = old
    }

    private enum CodingKeys: String, CodingKey {
        case baseline
        case field
        case locallyEdited = "locally_edited"
        case new
        case old
    }
}

