/// Paginated list of solution tag summaries returned by the list solution tags endpoint.
public struct SolutionTagListResponse: Codable, Sendable {
    /// Array of solution tag objects for the current page.
    public var data: [SolutionTagSummary]
    /// `true` if a subsequent page exists; `false` when this is the last page.
    public var hasNext: Bool
    /// `true` if a preceding page exists; `false` when this is the first page.
    public var hasPrev: Bool
    /// Current page number (1-indexed).
    public var page: Int
    /// Maximum number of results returned per page.
    public var pageSize: Int
    /// Total number of distinct solution tags across all pages, after deduplication by key.
    public var totalEntries: Int
    /// Total number of pages available at the current `page_size`.
    public var totalPages: Int

    public init(
        data: [SolutionTagSummary],
        hasNext: Bool,
        hasPrev: Bool,
        page: Int,
        pageSize: Int,
        totalEntries: Int,
        totalPages: Int
    ) {
        self.data = data
        self.hasNext = hasNext
        self.hasPrev = hasPrev
        self.page = page
        self.pageSize = pageSize
        self.totalEntries = totalEntries
        self.totalPages = totalPages
    }

    private enum CodingKeys: String, CodingKey {
        case data
        case hasNext = "has_next"
        case hasPrev = "has_prev"
        case page
        case pageSize = "page_size"
        case totalEntries = "total_entries"
        case totalPages = "total_pages"
    }
}

/// The outcome of a solution upgrade operation, including the computed diff and conflict status.
public struct SolutionUpgradeResult: Codable, Sendable {
    /// Ordered list of individual config change entries representing every add, update, noop, orphan, and delete in the diff.
    public var changes: [SolutionDiffEntry]
    /// Machine-readable conflict code when `status` is `"conflict"`, e.g. `"review_required"`. `null` when there is no conflict.
    public var code: String?
    /// `true` when the upgrade was computed without writing any changes; `false` when changes were committed.
    public var dryRun: Bool
    /// Version string of the currently installed solution, as declared in its manifest. `null` if no prior version is installed.
    public var existingSolutionVersion: String?
    /// Version string of the incoming solution to be installed, as declared in its manifest. `null` if the incoming manifest omits a version.
    public var incomingSolutionVersion: String?
    /// Human-readable description of the conflict or error. `null` when there is no conflict.
    public var message: String?
    /// Opaque fingerprint that uniquely identifies this diff. Pass this value as `review_fingerprint` on a subsequent non-dry-run upgrade call to confirm you have reviewed the diff. `null` if not applicable.
    public var reviewFingerprint: String?
    /// Overall result of the upgrade. `"ready"` means the upgrade can proceed; `"conflict"` means a blocking issue was detected and the upgrade was not applied.
    public var status: String
    /// Aggregate counts of each action type across all diff entries.
    public var summary: SolutionDiffSummary
    /// Describes the nature of the version transition. One of `"upgrade"`, `"downgrade"`, `"same"`, or `"unknown"`.
    public var versionChange: String

    public init(
        changes: [SolutionDiffEntry],
        code: String? = nil,
        dryRun: Bool,
        existingSolutionVersion: String? = nil,
        incomingSolutionVersion: String? = nil,
        message: String? = nil,
        reviewFingerprint: String? = nil,
        status: String,
        summary: SolutionDiffSummary,
        versionChange: String
    ) {
        self.changes = changes
        self.code = code
        self.dryRun = dryRun
        self.existingSolutionVersion = existingSolutionVersion
        self.incomingSolutionVersion = incomingSolutionVersion
        self.message = message
        self.reviewFingerprint = reviewFingerprint
        self.status = status
        self.summary = summary
        self.versionChange = versionChange
    }

    private enum CodingKeys: String, CodingKey {
        case changes
        case code
        case dryRun = "dry_run"
        case existingSolutionVersion = "existing_solution_version"
        case incomingSolutionVersion = "incoming_solution_version"
        case message
        case reviewFingerprint = "review_fingerprint"
        case status
        case summary
        case versionChange = "version_change"
    }
}

/// Response returned by the solution upgrade endpoint, containing the solution record, the full upgrade diff, and the resulting installed configs.
public struct SolutionUpgradeResponse: Codable, Sendable {
    /// When the solution config record was first created (ISO 8601). `null` if unavailable.
    public var createdAt: Date?
    /// Config ID of the solution record (`cfg_...`).
    public var id: String
    /// List of config entries that were installed or updated as part of this upgrade. Empty when `dry_run` is `true` or when no configs changed.
    public var installedConfigs: [InstalledConfigEntry]?
    /// Object type discriminator. Always `"Solution"`.
    public var kind: String
    /// Human-readable stable identifier for this solution config. `null` if not assigned.
    public var lookupKey: String?
    /// Summary of the solution being upgraded, including its name, manifest metadata, and tag keys.
    public var solution: SolutionSummary
    /// When the solution config record was last modified (ISO 8601). `null` if unavailable.
    public var updatedAt: Date?
    /// Detailed result of the upgrade operation, including the computed diff and any conflict information.
    public var upgradeResult: SolutionUpgradeResult
    /// Hierarchical path of the solution in the config tree. `null` if not assigned.
    public var virtualPath: String?

    public init(
        createdAt: Date? = nil,
        id: String,
        installedConfigs: [InstalledConfigEntry]? = nil,
        kind: String,
        lookupKey: String? = nil,
        solution: SolutionSummary,
        updatedAt: Date? = nil,
        upgradeResult: SolutionUpgradeResult,
        virtualPath: String? = nil
    ) {
        self.createdAt = createdAt
        self.id = id
        self.installedConfigs = installedConfigs
        self.kind = kind
        self.lookupKey = lookupKey
        self.solution = solution
        self.updatedAt = updatedAt
        self.upgradeResult = upgradeResult
        self.virtualPath = virtualPath
    }

    private enum CodingKeys: String, CodingKey {
        case createdAt = "created_at"
        case id
        case installedConfigs = "installed_configs"
        case kind
        case lookupKey = "lookup_key"
        case solution
        case updatedAt = "updated_at"
        case upgradeResult = "upgrade_result"
        case virtualPath = "virtual_path"
    }
}
